QList<ManualSection> get_manual_document(bool include_pomodoro_plugin,
                                         bool include_feynman_plugin,
                                         bool include_mapamental_plugin,
                                         bool include_audiolivro_plugin,
                                         bool include_agenda_plugin,
                                         bool include_gantt_plugin)
{
    Q_UNUSED(include_mapamental_plugin);
    Q_UNUSED(include_audiolivro_plugin);

    QList<ManualSection> document = en_document();

    if (include_feynman_plugin) {
        document.append(feynman_en_document());
    }
    if (include_pomodoro_plugin) {
        document.append(pomodoro_en_document());
    }
    if (include_agenda_plugin) {
        document.append(agenda_en_document());
    }
    if (include_gantt_plugin) {
        document.append(gantt_en_document());
    }

    document.append(final_sections_en_document());
    return document;
}

